<header class="admin-page-head compact-head"><div><p class="admin-eyebrow">Configuration / public voice</p><h1>Site settings</h1><p class="admin-lede">Update the words and contact details the public site reads from MySQL. Deployment credentials stay in the private config file.</p></div></header>
<?php if (!empty($admin_error)): ?><div class="admin-state-card <?= e($admin_repository->status()) ?>"><span class="state-dot"></span><div><strong>Settings status</strong><p><?= e($admin_error) ?></p></div></div><?php endif; ?>
<?php if (!empty($errors)): ?><div class="admin-alert error" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="settings-form" method="post" action="<?= e(admin_url('/settings')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>">
    <?php $groups = array(); foreach ($setting_keys as $key => $definition) { $groups[$definition['group']][$key] = $definition; } $groupIndex = 0; ?>
    <?php foreach ($groups as $group => $groupKeys): $groupIndex++; ?><section class="admin-panel settings-panel"><div class="panel-heading"><div><p class="admin-eyebrow">0<?= e($groupIndex) ?> / <?= e(strtolower($group)) ?></p><h2><?= e($group) ?></h2></div><?php if ($group === 'Site identity'): ?><span class="setting-note">Contact and identity</span><?php elseif ($group === 'Homepage'): ?><span class="setting-note">Hero copy</span><?php elseif ($group === 'Footer'): ?><span class="setting-note">Closing scene</span><?php else: ?><span class="setting-note">Editorial pages</span><?php endif; ?></div><div class="settings-grid"><?php foreach ($groupKeys as $key => $definition): ?><label class="setting-field <?= $definition['type'] === 'textarea' ? 'span-2' : '' ?>"><span><?= e($definition['label']) ?><small><?= e($key) ?></small></span><?php if ($definition['type'] === 'textarea'): ?><textarea name="settings[<?= e($key) ?>]" maxlength="<?= e($definition['max']) ?>" rows="4"><?= e($settings[$key] ?? '') ?></textarea><?php else: ?><input type="<?= e($definition['type'] === 'url' ? 'url' : $definition['type']) ?>" name="settings[<?= e($key) ?>]" value="<?= e($settings[$key] ?? '') ?>" maxlength="<?= e($definition['max']) ?>" required><?php endif; ?></label><?php endforeach; ?></div></section><?php endforeach; ?>
    <div class="editor-submit settings-submit"><span class="settings-save-note">Changes are applied to public pages after saving.</span><button class="admin-primary-button" type="submit">Save all settings <span aria-hidden="true">↗</span></button></div>
</form>
